<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\GdprConsent\Domain;

final class GdprConsentMap
{
    /** @param array<string, GdprConsentPurposeItem> $items */
    private function __construct(private readonly array $items)
    {
    }

    public static function build(GdprConsentPurposeItem ...$items): self
    {
        $indexed = [];
        foreach ($items as $item) {
            $indexed[$item->key] = $item;
        }
        return new self($indexed);
    }

    public function findByKey(string $key): ?GdprConsentPurposeItem
    {
        return $this->items[$key] ?? null;
    }

    /** @return GdprConsentPurposeItem[] */
    public function all(): array
    {
        return array_values($this->items);
    }

    public function isEmpty(): bool
    {
        return empty($this->items);
    }
}
